import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/structure/commands.md","filePath":"modules/structure/commands.md","lastUpdated":0}`),a={name:`modules/structure/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>主命令是 <code>/emakistructure</code>, 你也可以简写成 <code>/ems</code> 或 <code>/estruct</code>. 直接输入主命令不带子命令时, 会输出用法提示; 如果输入了不认识的子命令, 提示里会告诉你用 <code>/ems help</code> 查看全部命令</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>需要权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/ems help</code></td><td>无 (所有人都能用)</td><td>列出所有命令</td></tr><tr><td><code>/ems get &lt;模板&gt; [朝向]</code></td><td><code>emakistructure.use</code></td><td>在你面前 3 格处临时摆出这个模板, 只为看效果 (不会写盘, 不会记进回滚日志)</td></tr><tr><td><code>/ems select pos1</code> / <code>pos2</code></td><td><code>emakistructure.edit</code></td><td>把你当前站的位置记为选区的第一个 / 第二个角点. 两个点必须在同一个世界, 否则会提示</td></tr><tr><td><code>/ems select adjust &lt;add|reduce&gt; &lt;front|back|left|right|up|down&gt; &lt;数值&gt;</code></td><td><code>emakistructure.edit</code></td><td>沿指定方向把选区扩大或缩小; 缩小过头会提示&quot;收缩过多&quot;</td></tr><tr><td><code>/ems select clear</code></td><td><code>emakistructure.edit</code></td><td>取消当前选区与线框</td></tr><tr><td><code>/ems structure export &lt;名称&gt; [entities]</code></td><td><code>emakistructure.edit</code></td><td>把当前选区导出成结构模板 <code>structures/&lt;名称&gt;.nbt</code> (原版 <code>.nbt</code> 结构文件, 不是多方块定义); <strong>默认不保存选区内的生物</strong>, 需要保存时在末尾加上 <code>entities</code></td></tr><tr><td><code>/ems structure place &lt;模板&gt; &lt;朝向&gt;</code></td><td><code>emakistructure.edit</code></td><td>在你站的位置放置这个结构模板; 朝向见下文. 多方块请改用 <code>/ems multiblock place</code></td></tr><tr><td><code>/ems multiblock export &lt;id&gt; [force]</code></td><td><code>emakistructure.edit</code></td><td>按选区把机关布局记录成 <code>multiblocks/&lt;id&gt;.yml</code> (只记录, 不会放置). 该 id 已存在时要加 <code>force</code> 才会覆盖</td></tr><tr><td><code>/ems multiblock place &lt;id&gt; [朝向]</code></td><td><code>emakistructure.edit</code></td><td>在你站的位置摆出这个多方块机关: 原版方块, 自定义方块与家具都会按朝向摆放, 放完自动开始形状检测</td></tr><tr><td><code>/ems multiblock list</code></td><td><code>emakistructure.admin</code></td><td>列出所有已加载的多方块定义, 以及成员数, 是否允许旋转, 进行中与已完成的数量</td></tr><tr><td><code>/ems multiblock validate &lt;id&gt;</code></td><td><code>emakistructure.admin</code></td><td>对现场形状再检查一次, 并列出成员数, 无法识别的自定义方块, 缺失的家具来源与实例数量</td></tr><tr><td><code>/ems reload</code></td><td><code>emakistructure.reload</code></td><td>重新读取配置, 语言文件, 模板缓存与生物点位 / 家具缓存, 并显示已加载的模板数量</td></tr><tr><td><code>/ems debug ...</code></td><td><code>emakistructure.admin</code></td><td>转交给 CoreLib 的调试命令, 只输出 structure 模块的日志, 用于排查问题</td></tr></tbody></table><h2 id="朝向参数" tabindex="-1">朝向参数 <a class="header-anchor" href="#朝向参数" aria-label="Permalink to “朝向参数”">​</a></h2><p><code>get</code>, <code>structure place</code>, <code>multiblock place</code> 的 <code>[朝向]</code> 共 8 个可选值:</p><table tabindex="0"><thead><tr><th>取值</th><th>含义</th></tr></thead><tbody><tr><td><code>north</code> / <code>east</code> / <code>south</code> / <code>west</code></td><td>只旋转, 不镜像</td></tr><tr><td><code>north_mirror</code> / <code>east_mirror</code> / <code>south_mirror</code> / <code>west_mirror</code></td><td>旋转之后再做左右镜像</td></tr></tbody></table><p>不填朝向时, 插件按你当前面朝的方向自动取最近的一个 (东南西北之一). 填了不认识的值时, 提示里会列出可用值</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><p>权限在 <code>paper-plugin.yml</code> 中声明, 默认值如下:</p><table tabindex="0"><thead><tr><th>权限</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>emakistructure.use</code></td><td><code>true</code> (所有玩家)</td><td>使用预览命令 <code>get</code></td></tr><tr><td><code>emakistructure.edit</code></td><td><code>op</code></td><td>框选, 结构导出与放置, 多方块导出与放置</td></tr><tr><td><code>emakistructure.reload</code></td><td><code>op</code></td><td>重载配置</td></tr><tr><td><code>emakistructure.admin</code></td><td><code>op</code></td><td>管理与排查: <code>multiblock list</code> / <code>validate</code>, <code>debug</code>; 已包含上面全部子权限</td></tr></tbody></table><p>按 Tab 键自动补全时, 插件会按你的权限过滤子命令, 并补全模板名, 多方块 id, 朝向值, 以及 <code>adjust</code> 的方向和 <code>select</code> 的操作名; 你没有的权限对应的子命令不会出现</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to “使用示例”">​</a></h2><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 框选一个 12×8×12 的区域</span></span>
<span class="line"><span>/ems select pos1</span></span>
<span class="line"><span>/ems select pos2</span></span>
<span class="line"><span>/ems select adjust add up 3</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 导出为结构模板并就地预览</span></span>
<span class="line"><span>/ems structure export village_hub_a</span></span>
<span class="line"><span>/ems get village_hub_a north</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 朝南放置</span></span>
<span class="line"><span>/ems structure place village_hub_a south</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 记录一个多方块结构 (按选区)</span></span>
<span class="line"><span>/ems multiblock export teleporter</span></span>
<span class="line"><span>/ems multiblock place teleporter east</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查看已加载的多方块定义与状态</span></span>
<span class="line"><span>/ems multiblock list</span></span>
<span class="line"><span>/ems multiblock validate teleporter</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 重载</span></span>
<span class="line"><span>/ems reload</span></span></code></pre></div><div class="caution custom-block"><p class="custom-block-title custom-block-title-default">CAUTION</p><p><code>structure export</code> 导出的是<strong>原版 <code>.nbt</code> 结构文件</strong> (存放在 <code>structures/</code> 目录), <code>multiblock export</code> 导出的是<strong>自己的多方块布局定义</strong> (存放在 <code>multiblocks/</code> 目录). 两者是两种不同的文件, 不能互相替换使用, 放置时也不能混用命令</p></div>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};